export default function SectionOverview() {
 return (
 <section id="overview" className="guide-section">
 <h2 className="guide-section__title">1. System Overview</h2>
 <p>
 The VoltWorks Plant Visitor Management system tracks every plant visit from the initial
 request through visitor departure. It coordinates work across three teams — Security,
 EHS (Environment, Health &amp; Safety), and Operations — to make sure every visitor is
 badged, briefed, and guided safely through the facility.
 </p>

 <h3 className="guide-section__subtitle">How a Visit Flows Through the System</h3>
 <div className="flow-diagram">
 <div className="flow-step">
 <span className="flow-step__number">1</span>
 <span className="flow-step__label">Visit Requested</span>
 <span className="flow-step__actor">👤 You submit</span>
 </div>
 <span className="flow-arrow" aria-hidden="true">→</span>
 <div className="flow-step">
 <span className="flow-step__number">2</span>
 <span className="flow-step__label">EHS Review (if needed)</span>
 <span className="flow-step__actor">⚙ System routes</span>
 </div>
 <span className="flow-arrow" aria-hidden="true">→</span>
 <div className="flow-step">
 <span className="flow-step__number">3</span>
 <span className="flow-step__label">Approved</span>
 <span className="flow-step__actor">👤 EHS approves</span>
 </div>
 <span className="flow-arrow" aria-hidden="true">→</span>
 <div className="flow-step">
 <span className="flow-step__number">4</span>
 <span className="flow-step__label">Tasks Created</span>
 <span className="flow-step__actor">⚙ System generates</span>
 </div>
 <span className="flow-arrow" aria-hidden="true">→</span>
 <div className="flow-step">
 <span className="flow-step__number">5</span>
 <span className="flow-step__label">Check In / Out</span>
 <span className="flow-step__actor">👤 Front desk</span>
 </div>
 </div>

 <h3 className="guide-section__subtitle">Key Concepts</h3>
 <dl className="definition-list">
 <dt>Visit Request</dt>
 <dd>
 The master record for a planned visit. It captures who is coming, when, where in
 the plant they need to go, and what type of visit it is.
 </dd>
 <dt>Production Zone</dt>
 <dd>
 A defined area of the plant (e.g., Paint Shop, Battery Assembly, Quality Lab).
 Each zone has an <strong>access tier</strong>: Standard (open), Restricted (requires
 EHS approval), or Prohibited (no visitor access).
 </dd>
 <dt>Fulfillment Task</dt>
 <dd>
 A preparation task assigned to a specific team — Security (badge preparation),
 EHS (safety briefing), or Operations (tour guide assignment). These are created
 automatically after a visit is approved.
 </dd>
 <dt>Visitor</dt>
 <dd>
 An individual person on a visit. Each visitor has their own check-in time, check-out
 time, NDA status, and contact information.
 </dd>
 </dl>
 </section>
 );
}
