export default function SectionSubmitVisit() {
 return (
 <section id="submit-visit" className="guide-section">
 <h2 className="guide-section__title">2. Submitting a Visit Request</h2>
 <p>
 Any plant team member can submit a visit request. This is always the first step — no
 visitor can enter the facility without a request on record.
 </p>

 <h3 className="guide-section__subtitle">Step-by-Step Instructions</h3>
 <ol className="step-list">
 <li className="step-list__item">
 <span className="step-list__action">👤 Your Action</span>
 <p>
 Open the application navigator on the left side of the screen. Under{" "}
 <strong>VoltWorks Plant Operations → Visits</strong>, click{" "}
 <strong>Submit New Visit Request</strong>. A blank form opens.
 </p>
 </li>
 <li className="step-list__item">
 <span className="step-list__action">👤 Your Action</span>
 <p>Fill in the required fields on the form:</p>
 <table className="field-table">
 <thead>
 <tr>
 <th>Field</th>
 <th>What to Enter</th>
 </tr>
 </thead>
 <tbody>
 <tr>
 <td><strong>Visit Type</strong></td>
 <td>
 Select one: Investor Tour, Customer Delivery, Supplier Audit,
 Contractor Access, Regulatory Inspection, or VIP Executive Visit.
 </td>
 </tr>
 <tr>
 <td><strong>Purpose</strong></td>
 <td>Briefly describe why the visit is happening.</td>
 </tr>
 <tr>
 <td><strong>Host Employee</strong></td>
 <td>The employee who will be the primary contact for this visit.</td>
 </tr>
 <tr>
 <td><strong>Scheduled Start / End</strong></td>
 <td>The planned date and time window for the visit.</td>
 </tr>
 <tr>
 <td><strong>Expected Visitors</strong></td>
 <td>The number of people expected to attend.</td>
 </tr>
 <tr>
 <td><strong>Production Zones</strong></td>
 <td>
 Select which plant areas visitors will need to access. Pay special
 attention to zone access tiers — choosing a <em>Restricted</em> zone
 triggers the EHS approval process (see Section 3).
 </td>
 </tr>
 <tr>
 <td><strong>Photography Permitted</strong></td>
 <td>Whether visitors are allowed to take photos on site.</td>
 </tr>
 <tr>
 <td><strong>Personal Devices Permitted</strong></td>
 <td>Whether visitors may bring personal electronic devices.</td>
 </tr>
 </tbody>
 </table>
 </li>
 <li className="step-list__item">
 <span className="step-list__action">👤 Your Action</span>
 <p>
 Click <strong>Submit</strong> to save the request. The system assigns it a unique
 number and sets the state to <strong>Requested</strong>.
 </p>
 </li>
 <li className="step-list__item">
 <span className="step-list__action">⚙ System Automatic</span>
 <p>
 The system immediately evaluates the request. What happens next depends on the
 visit type and the zones you selected:
 </p>
 <ul className="sub-list">
 <li>
 <strong>Regulatory Inspection</strong> → The system automatically approves the
 visit (bypasses EHS review) and sets the state to <strong>Approved</strong>.
 </li>
 <li>
 <strong>Any restricted zone selected</strong> → The system routes the visit to
 <strong> Pending EHS Approval</strong> (see Section 3).
 </li>
 <li>
 <strong>No restricted zones, not regulatory</strong> → The request stays in
 <strong> Requested</strong> state for supervisor review.
 </li>
 </ul>
 </li>
 </ol>

 <div className="callout callout--info">
 <strong>Tip:</strong> After submitting, you can always find your request under{" "}
 <strong>VoltWorks Plant Operations → Visits → My Visit Requests</strong>. This shows
 all requests you have created, sorted with the newest first.
 </div>
 </section>
 );
}
