export default function SectionEhsApproval() {
 return (
 <section id="ehs-approval" className="guide-section">
 <h2 className="guide-section__title">3. EHS Approval Process for Restricted Zones</h2>
 <p>
 The plant has areas with different security levels. When a visit request includes a
 zone classified as <strong>Restricted</strong>, the system automatically holds the
 request for EHS (Environment, Health &amp; Safety) review before it can proceed.
 </p>

 <h3 className="guide-section__subtitle">Understanding Zone Access Tiers</h3>
 <table className="field-table">
 <thead>
 <tr>
 <th>Access Tier</th>
 <th>Meaning</th>
 <th>EHS Review?</th>
 </tr>
 </thead>
 <tbody>
 <tr>
 <td><span className="tier-badge tier-badge--standard">Standard</span></td>
 <td>Open to visitors. General areas like lobbies, warehouses, and general access zones.</td>
 <td>No</td>
 </tr>
 <tr>
 <td><span className="tier-badge tier-badge--restricted">Restricted</span></td>
 <td>Requires special safety measures. Zones like Battery Assembly, Paint Shop, or Quality Lab may be restricted.</td>
 <td><strong>Yes — automatic</strong></td>
 </tr>
 <tr>
 <td><span className="tier-badge tier-badge--prohibited">Prohibited</span></td>
 <td>No visitor access under any circumstances.</td>
 <td>N/A — visitors cannot be scheduled here</td>
 </tr>
 </tbody>
 </table>

 <h3 className="guide-section__subtitle">What Happens Automatically</h3>
 <ol className="step-list">
 <li className="step-list__item">
 <span className="step-list__action">⚙ System Automatic</span>
 <p>
 When a new visit request is submitted with <strong>state = Requested</strong>,
 the system checks the selected production zones. If <em>any</em> of them have an
 access tier of <strong>Restricted</strong>, the system automatically changes the
 state to <strong>Pending EHS Approval</strong>.
 </p>
 </li>
 <li className="step-list__item">
 <span className="step-list__action">⚙ System Automatic</span>
 <p>
 The system displays an info message identifying which restricted zones triggered
 the review (for example: "Visit routed to EHS Approval — the following
 restricted zones were requested: Battery Assembly (BA-01), Paint Shop (PS-02)").
 </p>
 </li>
 </ol>

 <h3 className="guide-section__subtitle">Special Case: Regulatory Inspections</h3>
 <div className="callout callout--success">
 <strong>Bypass Rule:</strong> If the visit type is <strong>Regulatory Inspection</strong>,
 the system <em>automatically approves</em> the visit regardless of which zones are
 requested. Regulatory inspectors have priority access, and the system skips the EHS
 review entirely. The visit state goes directly to <strong>Approved</strong>.
 </div>

 <h3 className="guide-section__subtitle">Reviewing Pending Requests (EHS / Supervisors)</h3>
 <ol className="step-list">
 <li className="step-list__item">
 <span className="step-list__action">👤 EHS Reviewer Action</span>
 <p>
 Navigate to <strong>VoltWorks Plant Operations → Visits → Pending EHS Approval</strong>.
 This list shows all visit requests waiting for EHS safety review, sorted by
 scheduled start date.
 </p>
 </li>
 <li className="step-list__item">
 <span className="step-list__action">👤 EHS Reviewer Action</span>
 <p>
 Open a request and review the zones, visit type, purpose, and expected visitor
 count. Verify that appropriate safety measures can be arranged.
 </p>
 </li>
 <li className="step-list__item">
 <span className="step-list__action">👤 EHS Reviewer Action</span>
 <p>
 Change the <strong>State</strong> field to <strong>Approved</strong> to allow the
 visit to proceed, or to <strong>Rejected</strong> if the safety requirements
 cannot be met. Save the record.
 </p>
 </li>
 </ol>
 </section>
 );
}
