","/* ================================================
 VoltWorks User Guide — CSS
 Uses ServiceNow Horizon design tokens
 ================================================ */

:root {
 --snx-color-surface: rgb(var(--now-color_background--primary, 255, 255, 255));
 --snx-color-surface-alt: rgb(var(--now-color_background--secondary, 245, 247, 249));
 --snx-color-border: rgb(var(--now-color_border--primary, 207, 213, 215));
 --snx-color-text: rgb(var(--now-color_text--primary, 16, 23, 26));
 --snx-color-text-muted: rgb(var(--now-color_text--secondary, 75, 85, 89));
 --snx-color-text-tertiary: rgb(var(--now-color_text--tertiary, 115, 127, 132));
 --snx-color-primary: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 --snx-color-primary-light: rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.08);
 --snx-color-on-primary: rgb(var(--now-actionable_label--primary--color, 255, 255, 255));
 --snx-color-positive: rgb(var(--now-color--alert-positive-2, 38, 134, 81));
 --snx-color-positive-bg: rgba(var(--now-color--alert-positive-2, 38, 134, 81), 0.08);
 --snx-color-warning: rgb(var(--now-color--alert-warning-2, 186, 119, 9));
 --snx-color-warning-bg: rgba(var(--now-color--alert-warning-2, 186, 119, 9), 0.08);
 --snx-color-info: rgb(var(--now-color--alert-info-2, 0, 113, 143));
 --snx-color-info-bg: rgba(var(--now-color--alert-info-2, 0, 113, 143), 0.06);
 --snx-color-critical: rgb(var(--now-color--alert-critical-2, 179, 51, 51));
 --snx-font-body: var(--now-font-family, "Lato", Arial, sans-serif);
}

/* ---------- Reset ---------- */
*, *::before, *::after { box-sizing: border-box; }
body {
 margin: 0;
 padding: 0;
 font-family: var(--snx-font-body);
 font-size: var(--now-static-font-size--md, 1rem);
 line-height: 1.6;
 color: var(--snx-color-text);
 background-color: var(--snx-color-surface-alt);
}

h1, h2, h3, h4, p, ul, ol, dl, table { margin: 0; padding: 0; }

/* ---------- Layout ---------- */
.guide-layout {
 display: grid;
 grid-template-columns: 260px 1fr;
 min-height: 100vh;
}

/* ---------- Sidebar ---------- */
.guide-sidebar {
 position: sticky;
 top: 0;
 height: 100vh;
 overflow-y: auto;
 background-color: var(--snx-color-surface);
 border-right: 1px solid var(--snx-color-border);
 padding: var(--now-static-space--lg, 1rem);
}

.guide-sidebar__header {
 display: flex;
 align-items: center;
 gap: var(--now-static-space--sm, 0.5rem);
 padding-bottom: var(--now-static-space--lg, 1rem);
 margin-bottom: var(--now-static-space--md, 0.75rem);
 border-bottom: 1px solid var(--snx-color-border);
}

.guide-sidebar__icon { font-size: 1.4rem; }

.guide-sidebar__title {
 font-size: var(--now-static-font-size--lg, 1.25rem);
 font-weight: 700;
 color: var(--snx-color-text);
}

/* ---------- Table of Contents ---------- */
.toc__list {
 list-style: none;
 margin: 0;
 padding: 0;
}

.toc__item { margin-bottom: var(--now-static-space--xxs, 0.125rem); }

.toc__link {
 display: block;
 padding: var(--now-static-space--sm, 0.5rem) var(--now-static-space--md, 0.75rem);
 border-radius: var(--now-static-border-radius--lg, 0.5rem);
 color: var(--snx-color-text-muted);
 text-decoration: none;
 font-size: 0.875rem;
 line-height: 1.4;
 transition: background-color 100ms ease, color 100ms ease;
}

.toc__link:hover {
 background-color: var(--snx-color-surface-alt);
 color: var(--snx-color-text);
}

.toc__link--active {
 background-color: var(--snx-color-primary-light);
 color: var(--snx-color-primary);
 font-weight: 600;
}

/* ---------- Main Content ---------- */
.guide-main {
 max-width: 900px;
 margin: 0 auto;
 padding: var(--now-static-space--xl, 1.5rem) var(--now-static-space--xxl, 2rem)
 var(--now-static-space--3xl, 2.5rem);
}

/* ---------- Hero ---------- */
.guide-hero {
 margin-bottom: var(--now-static-space--xxl, 2rem);
 padding-bottom: var(--now-static-space--xxl, 2rem);
 border-bottom: 2px solid var(--snx-color-border);
}

.guide-hero__title {
 font-size: 2rem;
 font-weight: 700;
 color: var(--snx-color-text);
 margin-bottom: var(--now-static-space--xs, 0.25rem);
}

.guide-hero__subtitle {
 font-size: var(--now-static-font-size--lg, 1.25rem);
 color: var(--snx-color-primary);
 font-weight: 600;
 margin-bottom: var(--now-static-space--lg, 1rem);
}

.guide-hero__intro {
 color: var(--snx-color-text-muted);
 line-height: 1.7;
 margin-bottom: var(--now-static-space--lg, 1rem);
}

.guide-hero__legend {
 display: flex;
 gap: var(--now-static-space--lg, 1rem);
 flex-wrap: wrap;
}

.legend-tag {
 display: inline-flex;
 align-items: center;
 gap: var(--now-static-space--xs, 0.25rem);
 padding: var(--now-static-space--xs, 0.25rem) var(--now-static-space--md, 0.75rem);
 border-radius: var(--now-static-border-radius--lg, 0.5rem);
 font-size: 0.875rem;
 font-weight: 600;
}

.legend-tag--auto {
 background-color: var(--snx-color-info-bg);
 color: var(--snx-color-info);
}

.legend-tag--user {
 background-color: var(--snx-color-positive-bg);
 color: var(--snx-color-positive);
}

/* ---------- Sections ---------- */
.guide-section {
 margin-bottom: var(--now-static-space--3xl, 2.5rem);
 padding-bottom: var(--now-static-space--xxl, 2rem);
 border-bottom: 1px solid var(--snx-color-border);
}

.guide-section:last-child { border-bottom: none; }

.guide-section__title {
 font-size: 1.6rem;
 font-weight: 700;
 color: var(--snx-color-text);
 margin-bottom: var(--now-static-space--lg, 1rem);
 padding-top: var(--now-static-space--lg, 1rem);
}

.guide-section__subtitle {
 font-size: var(--now-static-font-size--lg, 1.25rem);
 font-weight: 600;
 color: var(--snx-color-text);
 margin-top: var(--now-static-space--xl, 1.5rem);
 margin-bottom: var(--now-static-space--md, 0.75rem);
}

.guide-section p {
 color: var(--snx-color-text);
 line-height: 1.7;
 margin-bottom: var(--now-static-space--md, 0.75rem);
}

/* ---------- Step Lists ---------- */
.step-list {
 list-style: none;
 margin: 0 0 var(--now-static-space--lg, 1rem) 0;
 padding: 0;
 counter-reset: step-counter;
}

.step-list__item {
 position: relative;
 padding: var(--now-static-space--lg, 1rem);
 margin-bottom: var(--now-static-space--sm, 0.5rem);
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--now-static-border-radius--lg, 0.5rem);
 counter-increment: step-counter;
}

.step-list__item::before {
 content: counter(step-counter);
 position: absolute;
 top: var(--now-static-space--lg, 1rem);
 left: calc(-0.375rem - 1px);
 width: 1.5rem;
 height: 1.5rem;
 background-color: var(--snx-color-primary);
 color: var(--snx-color-on-primary);
 border-radius: 50%;
 display: flex;
 align-items: center;
 justify-content: center;
 font-size: 0.75rem;
 font-weight: 700;
 line-height: 1;
}

.step-list__action {
 display: inline-block;
 padding: 0.125rem var(--now-static-space--sm, 0.5rem);
 border-radius: var(--now-static-border-radius--md, 0.25rem);
 font-size: 0.75rem;
 font-weight: 700;
 text-transform: uppercase;
 letter-spacing: 0.04em;
 margin-bottom: var(--now-static-space--xs, 0.25rem);
 background-color: var(--snx-color-positive-bg);
 color: var(--snx-color-positive);
}

.step-list__item:has(.step-list__action:first-child) .step-list__action {
 background-color: var(--snx-color-positive-bg);
 color: var(--snx-color-positive);
}

.sub-list {
 list-style: disc;
 padding-left: var(--now-static-space--xl, 1.5rem);
 margin-top: var(--now-static-space--sm, 0.5rem);
 margin-bottom: var(--now-static-space--sm, 0.5rem);
}

.sub-list li {
 margin-bottom: var(--now-static-space--xs, 0.25rem);
 line-height: 1.6;
}

/* ---------- Tables ---------- */
.field-table {
 width: 100%;
 border-collapse: collapse;
 margin: var(--now-static-space--md, 0.75rem) 0 var(--now-static-space--lg, 1rem);
 font-size: 0.9rem;
}

.field-table thead th {
 background-color: var(--snx-color-surface-alt);
 color: var(--snx-color-text);
 font-weight: 600;
 text-align: left;
 padding: var(--now-static-space--sm, 0.5rem) var(--now-static-space--md, 0.75rem);
 border-bottom: 2px solid var(--snx-color-border);
}

.field-table tbody td {
 padding: var(--now-static-space--sm, 0.5rem) var(--now-static-space--md, 0.75rem);
 border-bottom: 1px solid var(--snx-color-border);
 vertical-align: top;
 line-height: 1.5;
}

.field-table tbody tr:last-child td { border-bottom: none; }

/* ---------- Flow Diagram ---------- */
.flow-diagram {
 display: flex;
 align-items: center;
 gap: var(--now-static-space--sm, 0.5rem);
 padding: var(--now-static-space--lg, 1rem);
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--now-static-border-radius--lg, 0.5rem);
 margin: var(--now-static-space--lg, 1rem) 0;
 overflow-x: auto;
 flex-wrap: wrap;
 justify-content: center;
}

.flow-step {
 display: flex;
 flex-direction: column;
 align-items: center;
 text-align: center;
 min-width: 7rem;
 gap: var(--now-static-space--xxs, 0.125rem);
}

.flow-step__number {
 width: 2rem;
 height: 2rem;
 background-color: var(--snx-color-primary);
 color: var(--snx-color-on-primary);
 border-radius: 50%;
 display: flex;
 align-items: center;
 justify-content: center;
 font-weight: 700;
 font-size: 0.875rem;
}

.flow-step__label {
 font-weight: 600;
 font-size: 0.85rem;
 color: var(--snx-color-text);
}

.flow-step__actor {
 font-size: 0.75rem;
 color: var(--snx-color-text-muted);
}

.flow-arrow {
 font-size: 1.25rem;
 color: var(--snx-color-text-tertiary);
 flex-shrink: 0;
}

/* ---------- State Flow ---------- */
.state-flow {
 display: flex;
 align-items: center;
 gap: var(--now-static-space--sm, 0.5rem);
 margin: var(--now-static-space--md, 0.75rem) 0;
 flex-wrap: wrap;
}

.state-note {
 font-size: 0.875rem;
 color: var(--snx-color-text-muted);
 font-style: italic;
}

/* ---------- State Badges ---------- */
.state-badge {
 display: inline-block;
 padding: 0.125rem var(--now-static-space--sm, 0.5rem);
 border-radius: var(--now-static-border-radius--lg, 0.5rem);
 font-size: 0.8rem;
 font-weight: 600;
 white-space: nowrap;
}

.state-badge--pending {
 background-color: var(--snx-color-info-bg);
 color: var(--snx-color-info);
}

.state-badge--in-progress {
 background-color: var(--snx-color-warning-bg);
 color: var(--snx-color-warning);
}

.state-badge--completed {
 background-color: var(--snx-color-positive-bg);
 color: var(--snx-color-positive);
}

.state-badge--cancelled {
 background: rgba(var(--now-color--alert-critical-2, 179, 51, 51), 0.08);
 color: var(--snx-color-critical);
}

/* ---------- Tier Badges ---------- */
.tier-badge {
 display: inline-block;
 padding: 0.125rem var(--now-static-space--sm, 0.5rem);
 border-radius: var(--now-static-border-radius--md, 0.25rem);
 font-size: 0.8rem;
 font-weight: 600;
}

.tier-badge--standard {
 background-color: var(--snx-color-positive-bg);
 color: var(--snx-color-positive);
}

.tier-badge--restricted {
 background-color: var(--snx-color-warning-bg);
 color: var(--snx-color-warning);
}

.tier-badge--prohibited {
 background: rgba(var(--now-color--alert-critical-2, 179, 51, 51), 0.08);
 color: var(--snx-color-critical);
}

/* ---------- Definition Lists ---------- */
.definition-list {
 margin: var(--now-static-space--md, 0.75rem) 0 var(--now-static-space--lg, 1rem);
}

.definition-list dt {
 font-weight: 700;
 color: var(--snx-color-text);
 margin-top: var(--now-static-space--md, 0.75rem);
}

.definition-list dd {
 margin-left: 0;
 padding-left: var(--now-static-space--lg, 1rem);
 color: var(--snx-color-text-muted);
 line-height: 1.6;
 margin-bottom: var(--now-static-space--sm, 0.5rem);
 border-left: 3px solid var(--snx-color-border);
}

/* ---------- Team Cards ---------- */
.team-cards {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
 gap: var(--now-static-space--lg, 1rem);
 margin: var(--now-static-space--lg, 1rem) 0;
}

.team-card {
 border: 1px solid var(--snx-color-border);
 border-radius: var(--now-static-border-radius--lg, 0.5rem);
 overflow: hidden;
 background-color: var(--snx-color-surface);
}

.team-card__header {
 display: flex;
 align-items: center;
 gap: var(--now-static-space--sm, 0.5rem);
 padding: var(--now-static-space--md, 0.75rem) var(--now-static-space--lg, 1rem);
 color: var(--snx-color-on-primary);
 font-weight: 700;
}

.team-card__header--security { background-color: var(--snx-color-info); }
.team-card__header--ehs { background-color: var(--snx-color-warning); }
.team-card__header--operations { background-color: var(--snx-color-positive); }

.team-card__icon { font-size: 1.2rem; }
.team-card__name { font-size: 1rem; }

.team-card__body {
 padding: var(--now-static-space--lg, 1rem);
}

.team-card__body p {
 margin-bottom: var(--now-static-space--xs, 0.25rem);
 font-size: 0.9rem;
}

/* ---------- Callouts ---------- */
.callout {
 padding: var(--now-static-space--lg, 1rem);
 border-radius: var(--now-static-border-radius--lg, 0.5rem);
 margin: var(--now-static-space--lg, 1rem) 0;
 line-height: 1.6;
 font-size: 0.925rem;
}

.callout--info {
 background-color: var(--snx-color-info-bg);
 border-left: 4px solid var(--snx-color-info);
 color: var(--snx-color-text);
}

.callout--warning {
 background-color: var(--snx-color-warning-bg);
 border-left: 4px solid var(--snx-color-warning);
 color: var(--snx-color-text);
}

.callout--success {
 background-color: var(--snx-color-positive-bg);
 border-left: 4px solid var(--snx-color-positive);
 color: var(--snx-color-text);
}

/* ---------- Tip Lists ---------- */
.tip-list {
 list-style: none;
 margin: var(--now-static-space--md, 0.75rem) 0;
 padding: 0;
}

.tip-list li {
 padding: var(--now-static-space--sm, 0.5rem) 0 var(--now-static-space--sm, 0.5rem)
 var(--now-static-space--lg, 1rem);
 border-left: 3px solid var(--snx-color-primary);
 margin-bottom: var(--now-static-space--sm, 0.5rem);
 line-height: 1.6;
}

/* ---------- Responsive ---------- */
@media (max-width: 768px) {
 .guide-layout {
 grid-template-columns: 1fr;
 }

 .guide-sidebar {
 position: static;
 height: auto;
 border-right: none;
 border-bottom: 1px solid var(--snx-color-border);
 }

 .guide-main {
 padding: var(--now-static-space--lg, 1rem);
 }

 .flow-diagram {
 flex-direction: column;
 }

 .flow-arrow {
 transform: rotate(90deg);
 }

 .team-cards {
 grid-template-columns: 1fr;
 }
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React from "react";
import ReactDOM from "react-dom/client";
import App from "./app";

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
","import React, { useState } from "react";
import TableOfContents from "./components/TableOfContents";
import SectionOverview from "./components/SectionOverview";
import SectionSubmitVisit from "./components/SectionSubmitVisit";
import SectionEhsApproval from "./components/SectionEhsApproval";
import SectionFulfillment from "./components/SectionFulfillment";
import SectionCheckInOut from "./components/SectionCheckInOut";
import SectionNavigation from "./components/SectionNavigation";
import SectionDashboard from "./components/SectionDashboard";
import SectionQuickRef from "./components/SectionQuickRef";
import "./app.css";

export default function App() {
 const [activeSection, setActiveSection] = useState("");

 const handleNavClick = (id: string) => {
 setActiveSection(id);
 const el = document.getElementById(id);
 if (el) {
 el.scrollIntoView({ behavior: "smooth", block: "start" });
 }
 };

 return (
 <div className="guide-layout">
 <aside className="guide-sidebar">
 <div className="guide-sidebar__header">
 <span className="guide-sidebar__icon" aria-hidden="true">📘</span>
 <span className="guide-sidebar__title">User Guide</span>
 </div>
 <TableOfContents activeSection={activeSection} onNavigate={handleNavClick} />
 </aside>
 <main className="guide-main">
 <header className="guide-hero">
 <h1 className="guide-hero__title">VoltWorks Plant Visitor Management</h1>
 <p className="guide-hero__subtitle">User Guide for Plant Operations Staff</p>
 <p className="guide-hero__intro">
 This guide walks you through every step of the visitor management process — from
 submitting a visit request to checking visitors out at the end of their stay.
 Throughout the guide, look for these labels to understand what happens automatically
 and what requires your action:
 </p>
 <div className="guide-hero__legend">
 <span className="legend-tag legend-tag--auto">⚙ System Automatic</span>
 <span className="legend-tag legend-tag--user">👤 Your Action Required</span>
 </div>
 </header>
 <SectionOverview />
 <SectionSubmitVisit />
 <SectionEhsApproval />
 <SectionFulfillment />
 <SectionCheckInOut />
 <SectionNavigation />
 <SectionDashboard />
 <SectionQuickRef />
 </main>
 </div>
 );
}
